import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Random;

public class CollectionsMasteryDemo {

    static class Task {
        final String name;
        final int priority;

        Task(String name, int priority) {
            this.name = name;
            this.priority = priority;
        }

        @Override
        public String toString() {
            return name + "(P:" + priority + ")";
        }
    }

    public static void main(String[] args) {
        // 1. Sorting with TimSort
        List<Integer> metrics = new ArrayList<>(Arrays.asList(42, 17, 89, 5, 23, 71, 12));
        Collections.sort(metrics);
        System.out.println("Sorted metrics: " + metrics);

        // 2. Binary Search & Insertion Index Math
        int searchKey = 50;
        int searchResult = Collections.binarySearch(metrics, searchKey);
        System.out.println("Binary search for " + searchKey + ": raw return = " + searchResult);
        if (searchResult < 0) {
            int insertionIndex = -(searchResult + 1);
            System.out.println("Value absent. Insert at index: " + insertionIndex);
            metrics.add(insertionIndex, searchKey);
            System.out.println("Metrics after precise insertion: " + metrics);
        }

        // 3. Permutations: reverse, swap, rotate
        Collections.reverse(metrics);
        System.out.println("Reversed: " + metrics);
        Collections.swap(metrics, 0, metrics.size() - 1);
        System.out.println("Swapped ends: " + metrics);

        // 4. Aggregations and queries
        List<String> tags = Arrays.asList("java", "backend", "java", "cloud", "k8s", "java");
        int javaFreq = Collections.frequency(tags, "java");
        System.out.println("Frequency of 'java': " + javaFreq);

        List<String> auditTags = Arrays.asList("frontend", "react", "css");
        boolean isDisjoint = Collections.disjoint(tags, auditTags);
        System.out.println("Disjoint check: " + isDisjoint);

        // 5. Defensive Unmodifiable Views
        List<String> internalBuffer = new ArrayList<>(Arrays.asList("CONFIG_A", "CONFIG_B"));
        List<String> secureView = Collections.unmodifiableList(internalBuffer);
        System.out.println("Unmodifiable view: " + secureView);

        try {
            secureView.add("UNAUTHORIZED_CONFIG");
        } catch (UnsupportedOperationException e) {
            System.out.println("Caught expected mutation prevention: " + e.getClass().getSimpleName());
        }

        // Note: mutation to backing list reflects in unmodifiable view
        internalBuffer.add("CONFIG_C");
        System.out.println("View after backing list update: " + secureView);
    }
}
```

