import java.util.Collections;
import java.util.List;

public class OrderedInserter {
    public static int insertSorted(List<Integer> sortedList, int target) {
        int index = Collections.binarySearch(sortedList, target);
        int insertPos = index >= 0 ? index : -(index + 1);
        sortedList.add(insertPos, target);
        return insertPos;
    }
}

