import java.util.Collections;
import java.util.List;

public class PermutationPipeline {
    public static void permute(List<Integer> numbers, int rotateDistance) {
        if (numbers == null || numbers.size() <= 1) return;
        Collections.rotate(numbers, rotateDistance);
        Collections.reverse(numbers);
    }
}

